INSERT INTO `cookbook_recipes` (`id`, `title`, `subtitle`, `description`, `ingredients`, `category_id`, `servings`, `time`, `calories`, `steps`, `images`, `step3`, `step4`, `step5`, `step6`) VALUES
(1, 'Ancho-Orange Chicken\r\n', 'with Kale Rice & Roasted Carrots\r\n', 'Weʼre amping up chicken breasts with a glaze of smoky ancho chile paste and fresh orange juice in this recipe. On the side, roasted carrots and lightly creamy, golden raisin-studded rice perfectly accent the sweetness of the glaze.\r\n', '4 Boneless, Skinless Chicken Breasts*\r\n1 Tbsp Ancho Chile Paste*\r\n2 Tbsps Crème Fraîche*\r\n3 Tbsps Golden Raisins*\r\n1 Lime*\r\n2 Tbsps Butter*\r\n2 Cloves Garlic*\r\n3/4 Jasmine Rice*\r\n4 Carrots*\r\n1 Bunch Kale', 3, 4, 45, 600, 'Place an oven rack in the center of the oven, then preheat to 450°F. In a medium pot, combine the rice, a big pinch of salt, and 1 1/2 cups of water. Heat to boiling on high. Once boiling, cover and reduce the heat to low. Cook 12 to 14 minutes, or until the water has been absorbed and the rice is tender. Turn off the heat and fluff with a fork. Cover to keep warm*While the rice cooks, wash and dry the fresh produce. Peel the carrots; quarter lengthwise, then halve crosswise. Peel and roughly chop the garlic. Remove and discard the stems of the kale; finely chop the leaves. Using a peeler, remove the lime rind, avoiding the white pith; mince to get 2 teaspoons of zest (or use a zester). Halve the lime crosswise. Halve the orange; squeeze the juice into a bowl, straining out any seeds. Whisk in the chile paste and 2 tablespoons of water until smooth.\r\n*Place the sliced carrots on a sheet pan. Drizzle with olive oil and season with salt and pepper; toss to coat. Arrange in an even layer. Roast 15 to 17 minutes, or until tender when pierced with a fork. Remove from the oven.*While the carrots roast, in a large pan (nonstick, if you have one), heat 2 teaspoons of olive oil on medium-high until hot. Add the chopped garlic and cook, stirring constantly, 30 seconds to 1 minute, or until fragrant. Add the chopped kale; season with salt and pepper. Cook, stirring occasionally, 3 to 4 minutes, or until slightly wilted. Add 1/3 cup of water; season with salt and pepper. Cook, stirring occasionally, 3 to 4 minutes, or until the kale has wilted and the water has cooked off. Transfer to the pot of cooked rice. Stir to combine; season with salt and pepper to taste. Cover to keep warm. Wipe out the pan.*While the carrots continue to roast, pat the chicken dry with paper towels; season with salt and pepper on both sides. In the same pan, heat 2 teaspoons of olive oil on medium-high until hot. Add the seasoned chicken and cook 4 to 6 minutes on the first side, or until browned. Flip and cook 2 to 3 minutes, or until lightly browned. Add the glaze and cook, frequently spooning the glaze over the chicken, 2 to 3 minutes, or until the chicken is coated and cooked through. Turn off the heat; stir the butter and the juice of 1 lime half into the glaze until the butter has melted. Season with salt and pepper to taste.*To the pot of cooked rice and kale, add the lime zest, crème fraîche, raisins, and the juice of the remaining lime half. Stir to combine; season with salt and pepper to taste. Serve the glazed chicken with the finished rice and roasted carrots. Top the chicken with the remaining glaze from the pan. Enjoy!', 'Recipe_Ancho-Orange_Chicken_with_Kale_Rice_Roasted_Carrots/0101_FPP_Chicken-Rice_18622_WEB_high_feature.jpg*Recipe_Ancho-Orange_Chicken_with_Kale_Rice_Roasted_Carrots/0101_FPP_Chicken-Rice_18594_WEB_high_feature.jpg*Recipe_Ancho-Orange_Chicken_with_Kale_Rice_Roasted_Carrots\\0101_FPP_Chicken-Rice_18622_WEB_high_feature.jpg*Recipe_Ancho-Orange_Chicken_with_Kale_Rice_Roasted_Carrots/0101_FPP_Chicken-Rice_18626_WEB_high_feature.jpg*Recipe_Ancho-Orange_Chicken_with_Kale_Rice_Roasted_Carrots/0101_FPP_Chicken-Rice_18630_WEB_high_feature.jpg*Recipe_Ancho-Orange_Chicken_with_Kale_Rice_Roasted_Carrots/0101_FPP_Chicken-Rice_18639_WEB_high_feature.jpg*Recipe_Ancho-Orange_Chicken_with_Kale_Rice_Roasted_Carrots/0101_FPP_Chicken-Rice_97338_WEB_SQ_hi_res.jpg', '', '', '', ''),
(2, 'Beef Medallions & Mushroom Sauce\r\n', 'with Mashed Potatoes\r\n', 'In this easy recipe, inspired by steak Diane (an American restaurant classic), weʼre searing beef medallions, then using the fond in the pan to make a rich, bright mushroom sauce for spooning on top. Garlic mashed potatoes and sautéed kale make for delicious, simple sides.\r\n', '4 oz Cremini Mushrooms*\r\n3⁄4 lb Yukon Gold Potatoes*\r\n2 cloves garlic*\r\n3/4 lb Yukon Gold Potatoes*\r\n1 bunch Kale*\r\n1 Shallot*\r\n2 Tbsps Butter*\r\n1 Tbsps Dijon Mustard*\r\n2 Tbsps Verjus Blacn\r\n', 5, 2, 30, 700, 'Heat a medium pot of salted water to boiling on high. Wash and dry the fresh produce. Large dice the potatoes. Peel the garlic. Using the flat side of your knife, smash 1 clove to flatten. Roughly chop the remaining clove. Peel and thinly slice the shallot. Remove and discard the stems of the kale; roughly chop the leaves. Thinly slice the mushrooms.*Add the diced potatoes and smashed garlic to the pot of boiling water and cook 13 to 15 minutes, or until tender when pierced with a fork. Turn off the heat. Drain thoroughly and return to the pot. Add half the butter and a drizzle of olive oil. Using a fork, mash to your desired consistency. Season with salt and pepper to taste. Cover to keep warm.*While the potatoes cook, in a large pan, heat 2 teaspoons of olive oil on medium-high until hot. Add the sliced shallot; season with salt and pepper. Cook, stirring occasionally, 1 to 2 minutes, or until softened. Add the chopped kale and 1/4 cup of water; season with salt and pepper. Cook, stirring frequently, 3 to 4 minutes, or until the kale has wilted and the water has cooked off. Transfer to a bowl and season with salt and pepper to taste. Cover with aluminum foil to keep warm. Rinse and wipe out the pan.*While the potatoes continue to cook, pat the beef dry with paper towels. Season with salt and pepper on both sides. In the same pan, heat 1 tablespoon of olive oil on medium-high until hot. Add the seasoned beef and cook 2 to 3 minutes per side for medium-rare, or until browned and cooked to your desired degree of doneness. Leaving any browned bits (or fond) in the pan, transfer to a plate and let rest for at least 5 minutes.*While the beef rests, add a drizzle of olive oil to the pan of reserved fond and heat on medium-high until hot. Add the sliced mushrooms in an even layer. Cook, without stirring, 2 to 3 minutes, or until browned. Add the chopped garlic; season with salt and pepper. Cook, stirring frequently, 1 to 2 minutes, or until softened and fragrant. Add the mustard, verjus, and 2 tablespoons of water (be careful, as the liquid may splatter); season with salt and pepper. Cook, stirring frequently and scraping up any fond, 30 seconds to 1 minute, or until thoroughly combined. Turn off the heat and stir in the remaining butter until melted. (If the sauce seems too thick, gradually add up to 2 tablespoons of water to achieve your desired consistency.) Season with salt and pepper to taste.*Serve the rested beef with the mashed potatoes and cooked kale. Top the beef and potatoes with the mushroom sauce. Enjoy!\r\n\r\n\r\n\r\n', 'Recipe_Beef_Medallions_Mushroom_Sauce_with_Mashed_Potatoes/0101_2PM_Steaks-Diane_18414_WEB_high_feature.jpg*Recipe_Beef_Medallions_Mushroom_Sauce_with_Mashed_Potatoes/0101_2PM_Steaks-Diane_18506_WEB_high_feature.jpg*Recipe_Beef_Medallions_Mushroom_Sauce_with_Mashed_Potatoes/0101_2PM_Steaks-Diane_18516_WEB_high_feature.jpg*Recipe_Beef_Medallions_Mushroom_Sauce_with_Mashed_Potatoes/0101_2PM_Steaks-Diane_18524_WEB_high_feature.jpg*Recipe_Beef_Medallions_Mushroom_Sauce_with_Mashed_Potatoes/0101_2PM_Steaks-Diane_18527_WEB_high_feature.jpg*Recipe_Beef_Medallions_Mushroom_Sauce_with_Mashed_Potatoes/0101_2PM_Steaks-Diane_18536_WEB_high_feature.jpg*Recipe_Beef_Medallions_Mushroom_Sauce_with_Mashed_Potatoes/0101_2PM_Steak-Diane_97315_SQ_hi_res.jpg', '', '', '', ''),
(3, 'Broccoli & Basil Pesto Sandwiches\r\n', 'with Romaine & Citrus Salad\r\n', 'These Italian focaccia sandwiches are layered with broccoli, three cheeses, and a savory basil, cashew, and pine nut pesto, then baked in the oven to meld all the bright, aromatic flavors. On the side, weʼre serving a refreshing salad of romaine and seasonal clementine, dressed in a creamy dressing made with fresh clementine juice.\r\n', '1 Piece Focaccia Bread*\r\n1 8-Ounce Can Tomato Sauce*\r\n1⁄2 lb Fresh Mozzarella Cheese*\r\n2 Clementines*\r\n2 cloves Garlic*\r\n2 Romaine Lettuce Hearts*\r\n1 lb Broccoli*\r\n1 oz Golden Or Red Sweet Piquante Peppers*\r\n2 Tbsps Crème Fraîche*\r\n1 Tbsp Dijon Mustard*\r\n1⁄2 cup Basil & Cashew Pesto (Contains Pine Nuts)*\r\n1⁄3 cup Shaved Parmesan Cheese*\r\n1 Tbsp Italian Seasoning (Whole Dried Basil, Sage, Oregano, Savory, Rosemary, Thyme, & Marjoram)\r\n', 1, 4, 45, 910, 'Place an oven rack in the center of the oven, then preheat to 475°F. Wash and dry the fresh produce. Cut off and discard the bottom 1/2 inch of the broccoli stem; cut the broccoli into small pieces, keeping the florets intact. Peel and roughly chop the garlic. Halve the focaccia. Grate the asiago cheese on the large side of a box grater. Tear the mozzarella cheese into small pieces. In a bowl, combine the tomato sauce and Italian seasoning; season with salt and pepper to taste.*In a large pan (nonstick, if you have one), heat 2 teaspoons of olive oil on medium-high until hot. Add the broccoli pieces; season with salt and pepper. Cook, stirring occasionally, 3 to 4 minutes, or until slightly softened. Add the chopped garlic; cook, stirring frequently, 1 to 2 minutes, or until slightly softened and fragrant. Add 1/2 cup of water; season with salt and pepper. Cook, stirring occasionally, 4 to 5 minutes, or until the broccoli has softened and the water has cooked off. Turn off the heat.*Line a sheet pan with foil. Place the halved focaccia on the foil, cut side up; drizzle with olive oil. Top with the seasoned tomato sauce. Top the focaccia bottom with the grated asiago cheese, half the mozzarella cheese, and the cooked broccoli. Evenly top the broccoli with the remaining mozzarella cheese and pesto (stirring before adding). Season both focaccia halves with salt and pepper. Bake, rotating the sheet pan halfway through, 11 to 13 minutes, or until lightly browned and the cheese has melted. Remove from the oven; let stand for at least 2 minutes. Transfer to a cutting board.*While the focaccia bakes, cut off and discard the root end of the lettuce; roughly chop the leaves. Place in a large bowl. Roughly chop the peppers. Halve 1 clementine crosswise; squeeze the juice into a bowl, straining out any seeds. Peel the remaining clementine; separate into segments. To make the dressing, add the crème fraîche, mustard, and 1 tablespoon of water to the bowl of clementine juice. Slowly whisk in a drizzle of olive oil until combined; season with salt and pepper to taste.*Just before serving, add the clementine segments, chopped peppers, and dressing to the bowl of chopped lettuce. Toss to thoroughly coat. Season with salt and pepper to taste.*Evenly top the baked focaccia bottom with the parmesan cheese. Complete with the focaccia top. Using a serrated knife, cut the finished sandwich into 4 equal-sized pieces. Serve with the salad on the side. Enjoy!\r\n\r\n\r\n\r\n\r\n\r\n', 'Recipe_Broccoli_Basil_Pesto_Sandwiches_with_Romaine_Citrus_Salad/1225_FPV_Pesto-Broccoli-Sandwich_18814_WEB_high_feature.jpg*\r\n\r\nRecipe_Broccoli_Basil_Pesto_Sandwiches_with_Romaine_Citrus_Salad/1225_FPV_Pesto-Broccoli-Sandwich_18818_WEB_high_feature.jpg*\r\n\r\nRecipe_Broccoli_Basil_Pesto_Sandwiches_with_Romaine_Citrus_Salad/1225_FPV_Pesto-Broccoli-Sandwich_18816_WEB_high_feature.jpg*\r\n\r\nRecipe_Broccoli_Basil_Pesto_Sandwiches_with_Romaine_Citrus_Salad/1225_FPV_Pesto-Broccoli-Sandwich_18819_WEB_high_feature.jpg*\r\n\r\nRecipe_Broccoli_Basil_Pesto_Sandwiches_with_Romaine_Citrus_Salad/1225_FPV_Pesto-Broccoli-Sandwich_18821_WEB_high_feature.jpg*\r\n\r\nRecipe_Broccoli_Basil_Pesto_Sandwiches_with_Romaine_Citrus_Salad/1225_FPV_Pesto-Broccoli-Sandwich_18823_WEB_high_feature.jpg*\r\n\r\nRecipe_Broccoli_Basil_Pesto_Sandwiches_with_Romaine_Citrus_Salad/1225_FPV_Pesto_-Broccoli-Sandwich_74916_WEB_SQ_hi_res.jpg', '', '', '', ''),
(4, 'Broccoli & Mozzarella Calzones\r\n', 'with Caesar Salad\r\n', 'These calzones are loaded with melty fresh mozzarella, creamy ricotta, and tender broccoli—balanced by a tangy tomato dipping sauce. For a refreshing side, weʼre tossing crunchy romaine and briny black olives in our take on Caesar dressing.\r\n', '11⁄2 lbs Pizza Dough*\r\n3 cloves Garlic*\r\n1 Romaine Lettuce Heart*\r\n1 lb Broccoli*\r\n1 cup Part-Skim Ricotta Cheese*\r\n1 8-Ounce Can Tomato Sauce*\r\n1⁄2 lb Fresh Mozzarella Cheese*\r\n1⁄4 cup Grated Parmesan Cheese*\r\n2 oz Black Cerignola Olives*\r\n1 Tbsp Italian Seasoning (Whole Dried Basil, Sage, Oregano, Savory, Rosemary, Thyme, & Marjoram)*\r\n1 Lemon\r\n', 1, 4, 50, 930, 'Remove the dough from the refrigerator to bring to room temperature. Place an oven rack in the center of the oven, then preheat to 475°F. Wash and dry the fresh produce. Cut off and discard the bottom 1/2 inch of the broccoli stem, then roughly chop the broccoli. Peel and roughly chop the garlic. Tear the mozzarella cheese into small pieces. Quarter and deseed the lemon.*In a large pan (nonstick, if you have one), heat 2 teaspoons of olive oil on medium-high until hot. Add the chopped broccoli; season with salt and pepper. Cook, stirring occasionally, 4 to 6 minutes, or until lightly browned. Add 2/3 of the chopped garlic. Cook, stirring constantly, 30 seconds to 1 minute, or until fragrant. Add 1/4 cup of water; season with salt and pepper. Cook, stirring occasionally, 2 to 3 minutes, or until the broccoli has softened and the water has cooked off. Transfer to a large bowl. Add the mozzarella cheese, ricotta cheese, half the Italian seasoning, and the juice of 1 lemon wedge; stir to combine. Season with salt and pepper. Wipe out the pan.*Lightly oil a sheet pan. Divide the dough into 2 equal-sized portions; using your hands and a rolling pin (or wine bottle), gently stretch and roll the portions into 1⁄4-inch-thick rounds. (If the dough is resistant, let rest for 5 minutes.) Divide the filling between the centers of the rounds; fold each round in half over the filling. Using a fork, crimp the edges of the dough to seal. Transfer to the sheet pan. Using a fork, poke a few holes across the tops of the calzones to vent. Lightly drizzle the calzones with olive oil. Bake 16 to 18 minutes, or until golden brown. Transfer to a cutting board and let stand for at least 2 minutes.*While the calzones bake, using the flat side of your knife, smash the olives; remove and discard the pits, then roughly chop. Cut off and discard the root end of the lettuce; roughly chop the leaves. To make the dressing, in a large bowl, combine the mayonnaise, half the parmesan cheese, the juice of the remaining lemon wedges, and a drizzle of olive oil. Season with salt and pepper to taste.*While the calzones continue to bake, in the pan used to cook the broccoli, heat 2 teaspoons of olive oil on medium-high until hot. Add the remaining chopped garlic; cook, stirring constantly, 30 seconds to 1 minute, or until fragrant. Add the tomato sauce and remaining Italian seasoning. Cook, stirring frequently, 2 to 3 minutes, or until slightly thickened. Turn off the heat and season with salt and pepper to taste.*Just before serving, add the chopped olives and lettuce to the bowl of dressing. Toss to coat; season with salt and pepper to taste. Cut the baked calzones in half. Serve with the sauce and salad on the side. Garnish with the remaining parmesan cheese. Enjoy!\r\n\r\n\r\n\r\n\r\n\r\n', 'Recipe_Broccoli_Mozzarella_Calzones_with_Caesar_Salad/0101_FPV_Broccoli0101_FPV_Broccoli-Mozzarella-Calzones_18498_WEB_high_feature.jpg*Recipe_Broccoli_Mozzarella_Calzones_with_Caesar_Salad/0101_FPV_Broccoli-Mozzarella-Calzones_18498_WEB_high_feature.jpg*Recipe_Broccoli_Mozzarella_Calzones_with_Caesar_Salad/0101_FPV_Broccoli-Mozzarella-Calzones_18532_WEB_high_feature.jpg*Recipe_Broccoli_Mozzarella_Calzones_with_Caesar_Salad/0101_FPV_Broccoli-Mozzarella-Calzones_18402_WEB_high_feature.jpg*Recipe_Broccoli_Mozzarella_Calzones_with_Caesar_Salad/0101_FPV_Broccoli-Mozzarella-Calzones_18428_WEB_retina_feature.jpg*Recipe_Broccoli_Mozzarella_Calzones_with_Caesar_Salad/0101_FPV_Broccoli-Calzones_97286_WEB_SQ_hi_res.jpg', '', '', '', ''),
(5, 'Bucatini Alfredo', 'with Broccoli', 'This quick-cooking recipe captures all the deliciously creamy, rich flavor of the classic Italian-American sauce—with the welcome addition of quick-braised broccoli. A dusting of pecorino cheese completes each bowl with a touch of sharpness.\r\n', '2 Tbsps Crème Fraîche*\r\n1⁄4 tsp Crushed Red Pepper Flakes 3 Tbsps* All-Purpose Flour*\r\n3 Tbsps All-Purpose Flour*\r\n1⁄4 cup Grated Pecorino Cheese*\r\n1 Head Broccoli*\r\n1-3 Cloves Garlic*\r\nOlive Oil*\r\n2 Tbsps Heavy Cream*\r\n2 Tbsps Verjus*\r\n1 Box Pasta\r\n', 1, 2, 25, 850, 'Heat a large pot of salted water to boiling on high. Wash and dry the fresh produce. Cut off and discard the bottom 1/2 inch of the broccoli stem; cut the broccoli into small pieces, keeping the florets intact. Peel and finely chop the garlic.*In a large pan, heat 2 teaspoons of olive oil on medium-high until hot. Add the broccoli pieces; season with salt and pepper. Cook, stirring occasionally, 4 to 5 minutes, or until slightly softened. Add 1/2 cup of water; season with salt and pepper. Cover the pan with aluminum foil and cook 3 to 4 minutes, or until the broccoli has softened and the water has cooked off. Transfer to a bowl. Wipe out the pan.*While the broccoli cooks, add the pasta to the pot of boiling water and cook 8 to 10 minutes, or until al dente (still slightly firm to the bite). Reserving 1⁄2 cup of the pasta cooking water, drain thoroughly.*While the pasta cooks, in a medium pan, heat 2 teaspoons of olive oil on medium-high until hot. Add the chopped garlic, capers, and as much of the red pepper flakes as you’d like, depending on how spicy you’d like the dish to be; season with salt and pepper. Cook, stirring constantly, 30 seconds to 1 minute, or until fragrant. Add the tomatoes and chopped olives; season with salt and pepper. Cook, stirring occasionally and gently crushing the tomatoes with the back of a spoon, 6 to 7 minutes, or until thickened. Turn off the heat and season with salt and pepper to taste.*In the same pan, heat 1 1/2 tablespoons of olive oil on medium-high until hot. Add the chopped garlic; season with salt and pepper. Cook, stirring constantly, 30 seconds to 1 minute, or until fragrant. Add the flour and as much of the red pepper flakes as you’d like, depending on how spicy you’d like the dish to be. Cook, stirring constantly, 30 seconds to 1 minute, or until thoroughly combined. Add the heavy cream (shaking the bottle just before opening), verjus, and 1 1/4 cups of water; season with salt and pepper. Cook, whisking frequently, 2 to 3 minutes, or until thickened; season with salt and pepper to taste.*\r\n\r\nAdd the cooked pasta, cooked broccoli, crème fraîche, and half the reserved pasta cooking water to the pan. Cook, stirring vigorously, 30 seconds to 1 minute, or until the pasta is thoroughly coated. (If the sauce seems dry, gradually add the remaining pasta cooking water to achieve your desired consistency.) Turn off the heat and season with salt and pepper to taste. Garnish the finished pasta with the cheese; season with pepper. Enjoy!\r\n\r\n\r\n\r\n\r\n\r\n', 'Recipe_Ancho-Orange_Chicken_with_Kale_Rice_Roasted_Carrots/0101_ING_FPP_large_feature.png*Recipe_Ancho-Orange_Chicken_with_Kale_Rice_Roasted_Carrots/0101_FPP_Chicken-Rice_18594_WEB_high_feature.jpg*Recipe_Ancho-Orange_Chicken_with_Kale_Rice_Roasted_Carrots\\0101_FPP_Chicken-Rice_18622_WEB_high_feature.jpg*Recipe_Ancho-Orange_Chicken_with_Kale_Rice_Roasted_Carrots/0101_FPP_Chicken-Rice_18626_WEB_high_feature.jpg*Recipe_Ancho-Orange_Chicken_with_Kale_Rice_Roasted_Carrots/0101_FPP_Chicken-Rice_18630_WEB_high_feature.jpg*Recipe_Ancho-Orange_Chicken_with_Kale_Rice_Roasted_Carrots/0101_FPP_Chicken-Rice_18639_WEB_high_feature.jpg*Recipe_Ancho-Orange_Chicken_with_Kale_Rice_Roasted_Carrots/0101_FPP_Chicken-Rice_97338_WEB_SQ_hi_res.jpg', '', '', '', ''),
(6, 'Bucatini & Tomato Sauce\r\n', 'with Roasted Broccoli\r\n', 'Made with petite datterini tomatoes, the sauce for tonightʼs bucatini highlights briny olives and capers, hot red pepper flakes, and savory Grana Padano cheese. Weʼre mixing in roasted broccoli for contrasting texture and nutty-sweet flavor.\r\n', '6 oz Bucatini Pasta*\r\n1 14-Ounce Can Datterini Tomatoes*\r\n2 cloves Garlic*\r\n2 Tbsps Butter*\r\n1 Tbsp Capers*\r\n1 lb Broccoli*\r\n3⁄4 oz Grana Padano Cheese*\r\n1 oz Kalamata Olives*\r\n1⁄4 tsp Crushed Red Pepper Flakes*\r\n1 Tbsp Italian Seasoning (Whole Dried Basil, Sage, Oregano, Savory, Rosemary, Thyme, & Marjoram)*', 1, 2, 30, 670, 'Place an oven rack in the center of the oven, then preheat to 450°F. Heat a large pot of salted water to boiling on high. Wash and dry the fresh produce. Cut off and discard the bottom 1/2 inch of the broccoli stem; cut the broccoli into small pieces. Place on a sheet pan. Drizzle with olive oil and season with salt, pepper, and up to half the Italian seasoning (you will have extra); toss to coat. Arrange in an even layer. Roast 22 to 24 minutes, or until browned and tender when pierced with a fork. Remove from the oven.*While the broccoli roasts, peel and roughly chop the garlic. Using the flat side of your knife, smash the olives; remove and discard the pits, then roughly chop. Grate the cheese on the small side of a box grater.*While the broccoli continues to roast, add the pasta to the pot of boiling water and cook 8 to 10 minutes, or until al dente (still slightly firm to the bite). Turn off the heat. Reserving 1/2 cup of the pasta cooking water, drain thoroughly and return to the pot.*While the pasta cooks, in a medium pan, heat 2 teaspoons of olive oil on medium-high until hot. Add the chopped garlic, capers, and as much of the red pepper flakes as you’d like, depending on how spicy you’d like the dish to be; season with salt and pepper. Cook, stirring constantly, 30 seconds to 1 minute, or until fragrant. Add the tomatoes and chopped olives; season with salt and pepper. Cook, stirring occasionally and gently crushing the tomatoes with the back of a spoon, 6 to 7 minutes, or until thickened. Turn off the heat and season with salt and pepper to taste.*To the pot of cooked pasta, add the roasted broccoli, sauce, butter, half the grated cheese, and half the reserved pasta cooking water; season with salt and pepper. Cook on medium-high, stirring vigorously, 1 to 2 minutes, or until the pasta is thoroughly coated. (If the sauce seems dry, gradually add the remaining pasta cooking water to achieve your desired consistency.) Turn off the heat and season with salt and pepper to taste. Garnish the finished pasta with the remaining grated cheese. Enjoy!\r\n\r\n\r\n\r\n\r\n', '', '', '', '', ''),
(7, 'Cheesy Enchiladas Rojas\r\n', 'with Mushrooms & Kale\r\n', 'Our hearty vegetarian enchiladas are filled with a combination of fragrant, Mexican- spiced rice and sautéed mushrooms and kale. For even more flavor, weʼre baking them under a smoky-sweet tomato sauce flavored with ancho chile paste and a layer of melty white cheddar. A dollop of lime-seasoned sour cream adds creamy, cooling balance. (You may receive green curly, dark green lacinato, or red kale.)\r\n', '8 Flour Tortillas*\r\n3⁄4 cup Jasmine Rice*\r\n1 28-Ounce Can Whole Peeled Tomatoes*\r\n4 oz Cremini Mushrooms*\r\n3 cloves Garlic*\r\n1 Yellow Onion*\r\n1 bunch Chives*\r\n2 Tbsps Ancho Chile Paste*\r\n1 Tbsp Mexican Spice Blend (Ancho Chile Powder, Sweet Paprika, Garlic Powder, Ground Cumin, & Whole Mexican Oregano)*\r\n1⁄2 lb White Cheddar Cheese*\r\n1⁄2 cup Sour Cream\r\n', 1, 4, 60, 750, 'Place an oven rack in the center of the oven, then preheat to 450°F. In a medium pot, combine the rice, half the spice blend, a big pinch of salt, and 1 1/2 cups of water. Heat to boiling on high. Once boiling, cover and reduce the heat to low. Cook 12 to 14 minutes, or until the water has been absorbed and the rice is tender. Turn off the heat and fluff with a fork. Transfer to a large bowl and set aside in a warm place.*While the rice cooks, wash and dry the fresh produce. Thinly slice the mushrooms. Remove and discard the stems of the kale; roughly chop the leaves. Peel and roughly chop the garlic. Peel and thinly slice the onion. Place the tomatoes in a bowl; gently break apart with your hands. Grate the cheese on the large side of a box grater. Thinly slice the chives. Halve the lime crosswise. In a bowl, combine the sour cream, the juice of 1 lime half, and a drizzle of olive oil; season with salt and pepper to taste.*In a large pan, heat 2 teaspoons of olive oil on medium-high until hot. Add the sliced mushrooms in an even layer. Cook, without stirring, 2 to 3 minutes, or until lightly browned. Add the chopped kale and 1/2 cup of water; season with salt and pepper. Cook, stirring frequently, 4 to 5 minutes, or until the kale has wilted and the water has cooked off. Transfer to the bowl of cooked rice; stir to combine. Wipe out the pan.*In the same pan, heat 2 teaspoons of olive oil on medium-high until hot. Add the chopped garlic and sliced onion; season with salt and pepper. Cook, stirring frequently, 4 to 5 minutes, or until softened. Add the chile paste and remaining spice blend; cook, stirring constantly, 30 seconds to 1 minute, or until dark red and fragrant. Add the tomatoes; season with salt and pepper. Cook, stirring frequently, 6 to 7 minutes, or until thickened. Turn off the heat. Season with salt and pepper to taste.*Add half the cheese and the juice of the remaining lime half to the bowl of filling. Stir to combine; season with salt and pepper to taste. Place the tortillas on a work surface. Spread about half the sauce into the bottom of a baking dish. Divide the finished filling among the tortillas; tightly roll up each tortilla around the filling. Transfer to the baking dish in a single layer, seam side down. Evenly top with the remaining sauce and remaining cheese.*\r\n\r\n\r\n\r\n', '', '', '', '', ''),
(8, 'Crispy Fish Sandwiches\r\n', 'with Tartar Sauce & Roasted Sweet Potato Wedges\r\n', 'These sandwiches highlight wild Alaskan pollock—flavored with aromatic seasonings, coated with panko breadcrumbs, and pan-fried for a golden-brown crust. In classic fashion, a tangy, mayo-based tartar sauce perfectly balances the fish.\r\n', '21 oz Wild Alaskan Pollock Fillets*\r\n2 Cage-Free Farm Eggs*\r\n2 Tbsps Sweet Pickle Relish*\r\n1 Romaine Lettuce Heart*\r\n1 Tbsp Weeknight Hero Spice Blend (Garlic Powder, Onion Powder, Smoked Paprika, & Whole Dried Parsley)*\r\n11⁄4 cups Panko Breadcrumbs*\r\n1⁄4 cup Creamy Mustard Sauce\r\n', 1, 4, 40, 790, 'Place an oven rack in the center of the oven, then preheat to 450°F. Wash and dry the fresh produce. Cut the sweet potatoes lengthwise into 1-inch-wide wedges. Place on a sheet pan. Drizzle with olive oil and season with salt and pepper; toss to coat. Arrange in an even layer, skin side down. Roast 27 to 29 minutes, or until browned and tender when pierced with a fork. Reserving the sheet pan, transfer to a plate and set aside in a warm place.*While the sweet potatoes roast, cut off and discard the root end of the lettuce; thinly slice the leaves. Halve the rolls. In a bowl, combine the mayonnaise, creamy mustard sauce, and sweet pickle relish. Season with salt and pepper to taste. Pat the fish fillets dry with paper towels. Halve crosswise.*While the sweet potatoes continue to roast, season the halved fish fillets on both sides with salt, pepper, and the spice blend. Crack the eggs into a bowl; season with salt and pepper. Beat until smooth. Place the breadcrumbs on a plate; season with salt and pepper. Working one piece at a time, thoroughly coat the seasoned fillets in the beaten eggs (letting any excess drip off), then in the breadcrumbs (pressing to adhere). Transfer to a separate plate.*While the sweet potatoes continue to roast, in a large pan (nonstick, if you have one), heat a thin layer of oil on medium-high until hot. Once the oil is hot enough that a pinch of breadcrumbs sizzles immediately when added, working in batches if necessary, add the breaded fish fillets. Cook 2 to 3 minutes per side, or until browned and cooked through. (If the pan seems dry, add 1 teaspoon of olive oil before flipping.) Transfer to a paper towel- lined plate; immediately season with salt and pepper.*While the fish cooks, place the rolls on the same sheet pan, cut side up. Drizzle with olive oil. Toast in the oven 4 to 5 minutes, or until lightly browned. Transfer to a clean work surface.*Divide the sauce, cooked fish fillets, and sliced lettuce among the toasted rolls. Serve the sandwiches with the roasted sweet potatoes on the side. Enjoy!\r\n\r\n\r\n\r\n\r\n\r\n', '', '', '', '', ''),
(9, 'General Tso\'s Chicken\r\n', 'with Bok Choy & Jasmine Rice\r\n', 'In this quick-cooking spin on a takeout favorite, hoisin sauce, honey, sriracha, and sesame oil lend our chicken the sweet, spicy, and nutty flavors General Tsoʼs is known for. A light dusting of cornstarch on the chicken just before it hits the pan creates a delicately crispy exterior (and helps it soak up the irresistible sauce later).\r\n', '10 oz Chopped Chicken Breast*\r\n1 head Baby Bok Choy*\r\n3⁄4 cup Jasmine Rice*\r\n2 cloves Garlic*\r\n1 Tbsp Rice Vinegar*\r\n1 1-Inch Piece Ginger*\r\n1 tsp Sriracha*\r\n1 Tbsp Honey*\r\n1 Tbsp Sesame Oil*\r\n1⁄4 cup Cornstarch*\r\n2 Tbsps Hoisin Sauce\r\n', 3, 2, 20, 700, 'Remove the honey from the refrigerator to bring to room temperature. In a medium saucepan, combine the rice, a big pinch of salt, and 1 1/2 cups of water; heat to boiling on high. Once boiling, cover and reduce the heat to low. Cook 12 to 14 minutes, or until the water has been absorbed and the rice is tender. Turn off the heat and fluff with a fork. Cover to keep warm.*While the rice cooks, pat the chicken dry with paper towels. Place in a large bowl and season with salt and pepper. Add the cornstarch; toss to thoroughly coat. In a medium pan, heat a thin layer of oil on medium-high until hot. Once the oil is hot enough that a piece of chicken sizzles immediately when added to the pan, add the coated chicken in an even layer (tapping off any excess cornstarch before adding). Cook, without stirring, 3 to 4 minutes, or until lightly browned. Continue to cook, stirring occasionally, 3 to 4 minutes, or until browned and cooked through. Leaving any browned bits (or fond) in the pan, transfer to a plate. Set aside in a warm place*While the chicken cooks, wash and dry the fresh produce. Cut off and discard the root end of the bok choy; roughly chop. Peel and finely chop the ginger. Peel and roughly chop the garlic. In a bowl, combine the hoisin sauce, vinegar, honey (kneading the packet before opening), sesame oil, 1 tablespoon of water, and as much of the sriracha as you’d like, depending on how spicy you’d like the dish to be.	*Add the chopped bok choy, ginger, and garlic to the pan of reserved fond; season with salt and pepper. (If the pan seems dry, add 1 tablespoon of olive oil.) Cook on medium-high, stirring frequently, 2 to 3 minutes, or until softened and fragrant. Add the sauce and cook, stirring constantly and scraping up any fond, 30 seconds to 1 minute, or until thoroughly combined.*Turn off the heat and add the cooked chicken to the pan; stir to thoroughly coat. Season with salt and pepper to taste. Serve the finished chicken and bok choy with the cooked rice. Enjoy!\r\n', '', '', '', '', ''),
(10, 'Hoisin-Glazed Pork Chops\r\n', 'with Stir-Fried Vegetables & Wonton Noodles\r\n', 'Delightfully chewy wonton noodles tossed in a nutty, savory sauce are a delicious accompaniment to these pork chops. For depth of flavor, weʼre pan-searing the pork chops, then glazing them with barbecue-like hoisin, whose sweetness perfectly matches bites of sautéed carrots in the noodles.\r\n', '4 Boneless, Center-Cut Pork Chops*\r\n2 Carrots*\r\n1 bunch Chives*\r\n2 Tbsps Tahini*\r\n2 Tbsps Soy Sauce*\r\n3⁄4 lb Fresh Wonton Noodles*\r\n2 tsps Sambal Oelek*\r\n1 1-Inch Piece Ginger*\r\n1⁄4 cup Hoisin Sauce\r\n', 4, 4, 30, 670, 'Fill a medium pot with water; add a pinch of salt. Heat to boiling on high. Wash and dry the fresh produce. Peel and finely chop the ginger. Cut out and discard the core of the cabbage; thinly slice the leaves. Peel the carrots and thinly slice into rounds. Thinly slice the chives.*In a large pan, heat 2 teaspoons of olive oil on medium-high until hot. Add the chopped ginger, sliced cabbage, and sliced carrots; season with salt and pepper. Cook, stirring occasionally, 4 to 5 minutes, or until softened and fragrant. Transfer to a bowl and cover with aluminum foil to keep warm. Rinse and wipe out the pan.*Pat the pork chops dry with paper towels; season with salt and pepper on both sides. In the same pan, heat 1 tablespoon of olive oil on medium-high until hot. Add the seasoned pork chops and cook 3 to 5 minutes on the first side, or until browned. Flip and cook 2 to 3 minutes, or until lightly browned. Add the hoisin sauce and 1/4 cup of water. Cook, frequently spooning the glaze over the pork, 2 to 3 minutes, or until the pork chops are coated and cooked through. Turn off the heat.*While the pork chops cook, in a bowl, whisk together the soy sauce, tahini, vinegar, and as much of the sambal oelek as you’d like, depending on how spicy you’d like the dish to be. Season with salt and pepper to taste.	*	While the pork chops continue to cook, using your hands, carefully separate the noodles and add to the pot of boiling water; cook, stirring occasionally, 2 to 4 minutes, or until tender. Turn off the heat. Drain thoroughly and return to the pot.*Add the cooked vegetables, sauce, and 1⁄4 cup of water to the pot of cooked noodles. Cook on medium-high, stirring constantly, 30 seconds to 1 minute, or until thoroughly combined. Turn off the heat. Season with salt and pepper to taste. Serve the finished noodles topped with the glazed pork chops (including any glaze from the pan). Garnish with the sliced chives. Enjoy!\r\n', '', '', '', '', ''),
(11, 'Honey-Butter Barramundi\r\n', 'with Za\'atar Roasted Vegetables\r\n', 'This Middle Eastern recipe pairs crispy barramundi—served in a family-friendly pan sauce of honey and butter—with a medley of winter vegetables. For savory, herby flavor, weʼre seasoning the vegetables with zaʼatar before roasting them.\r\n', '4 Skin-On Barramundi Fillets*\r\n1⁄2 cup Plain Greek Yogurt*\r\n11⁄8 lbs Yukon Gold Potatoes*\r\n1 Tbsp Za\'atar Seasoning (Ground Sumac, Sesame Seeds, Salt, Ground Thyme, Whole Dried Oregano, & Crushed Aleppo Pepper)*\r\n1-2 Carrots*\r\n1-3 Cloves Garlic*\r\n3-5 Radish*\r\n1 Lemon*\r\n2 Stems Parsley*\r\n2 Tbsp Honey\r\n', 2, 4, 45, 470, 'Remove the honey from the refrigerator to bring to room temperature. Place an oven rack in the center of the oven, then preheat to 450°F. Wash and dry the fresh produce. Halve the potatoes lengthwise; cut crosswise into 1/4- inch pieces. Peel the carrots; halve lengthwise, then cut crosswise into 1/2- inch pieces. Cut off and discard the ends of the radishes; quarter lengthwise, then halve crosswise. Quarter and deseed the lemon. Peel and finely chop the garlic; using the flat side of your knife, smash until it resembles a paste (or use a zester). Roughly chop the parsley leaves and stems.*Place the sliced potatoes and carrot pieces on a sheet pan. Drizzle with 1 tablespoon of olive oil; season with salt, pepper, and the za’atar seasoning. Toss to coat. Arrange in an even layer on one side of the sheet pan. Roast 12 to 14 minutes, or until lightly browned. Leaving the oven on, remove from the oven. Place the radish pieces in a bowl. Drizzle with olive oil and season with salt and pepper; toss to coat. Carefully arrange on the other side of the sheet pan. Roast 10 to 12 minutes, or until tender when pierced with a fork. Remove from the oven. Evenly top with the juice of 2 lemon wedges.*While the vegetables roast, in a bowl, combine the yogurt, the juice of the remaining lemon wedges, 1 tablespoon of olive oil, and as much of the garlic paste as you’d like. Drizzle with olive oil and season with salt and pepper to taste.*Once the vegetables have roasted for about 10 minutes, pat the fish fillets dry with paper towels; season with salt and pepper on both sides. In a large pan (nonstick, if you have one), heat 1 tablespoon of olive oil on medium-high until hot. Add the seasoned fillets, skin side down. Cook 4 to 6 minutes on the first side, or until lightly browned. Flip and add the butter. Cook, frequently spooning the butter over the fillets, 2 to 3 minutes, or until the fish is cooked through. Leaving the melted butter and any browned bits (or fond) in the pan, transfer the cooked fillets to a plate.*Add the honey (kneading the packet before opening) and 2 tablespoons of water to the pan of melted butter (be careful, as the liquid may splatter). Cook on medium-high, stirring frequently and scraping up any fond, 30 seconds to 1 minute, or until slightly thickened. Turn off the heat and season with salt and pepper to taste.*Serve the cooked fish fillets and roasted vegetables with the yogurt sauce on the side. Top the fish with the pan sauce. Garnish with the chopped parsley. Enjoy!\r\n', '', '', '', '', ''),
(12, 'Kale & Ricotta Quiche\r\n', 'with Romaine, Apple, & Almond Salad\r\n', 'This crowd-pleasing quiche showcases a rich, eggy filling made with ricotta and cream —balanced by hearty sautéed kale. On the side, weʼre serving a refreshing salad of crisp romaine and apple, wrapped in a creamy lemon dressing.\r\n', '4 Cage-Free Farm Eggs*\r\n1 Cup Part-Skim Ricotta Cheese*\r\n1 Romaine Lettuce Heart*\r\n2 Tbsps Sliced Roasted Almonds*\r\n1 Tbsp Cajun Spice Blend (Smoked Paprika, Ground Yellow Mustard, Onion Powder, Garlic Powder, Whole Dried Oregano, Whole Dried Thyme, & Cayenne Pepper)*\r\n2 Tbsps Crème Fraîche*\r\n1 Lemon*\r\nOlive Oil*\r\n1 Cup Kale\r\n', 1, 4, 55, 610, 'Remove the honey from the refrigerator to bring to room temperature. Place an oven rack in the center of the oven, then preheat to 450°F. Wash and dry the fresh produce. Halve the potatoes lengthwise; cut crosswise into 1/4- inch pieces. Peel the carrots; halve lengthwise, then cut crosswise into 1/2- inch pieces. Cut off and discard the ends of the radishes; quarter lengthwise, then halve crosswise. Quarter and deseed the lemon. Peel and finely chop the garlic; using the flat side of your knife, smash until it resembles a paste (or use a zester). Roughly chop the parsley leaves and stems.*Place the sliced potatoes and carrot pieces on a sheet pan. Drizzle with 1 tablespoon of olive oil; season with salt, pepper, and the za’atar seasoning. Toss to coat. Arrange in an even layer on one side of the sheet pan. Roast 12 to 14 minutes, or until lightly browned. Leaving the oven on, remove from the oven. Place the radish pieces in a bowl. Drizzle with olive oil and season with salt and pepper; toss to coat. Carefully arrange on the other side of the sheet pan. Roast 10 to 12 minutes, or until tender when pierced with a fork. Remove from the oven. Evenly top with the juice of 2 lemon wedges.*While the vegetables roast, in a bowl, combine the yogurt, the juice of the remaining lemon wedges, 1 tablespoon of olive oil, and as much of the garlic paste as you’d like. Drizzle with olive oil and season with salt and pepper to taste.*Once the vegetables have roasted for about 10 minutes, pat the fish fillets dry with paper towels; season with salt and pepper on both sides. In a large pan (nonstick, if you have one), heat 1 tablespoon of olive oil on medium-high until hot. Add the seasoned fillets, skin side down. Cook 4 to 6 minutes on the first side, or until lightly browned. Flip and add the butter. Cook, frequently spooning the butter over the fillets, 2 to 3 minutes, or until the fish is cooked through. Leaving the melted butter and any browned bits (or fond) in the pan, transfer the cooked fillets to a plate.*Add the honey (kneading the packet before opening) and 2 tablespoons of water to the pan of melted butter (be careful, as the liquid may splatter). Cook on medium-high, stirring frequently and scraping up any fond, 30 seconds to 1 minute, or until slightly thickened. Turn off the heat and season with salt and pepper to taste.*Serve the cooked fish fillets and roasted vegetables with the yogurt sauce on the side. Top the fish with the pan sauce. Garnish with the chopped parsley. Enjoy!', '', '', '', '', ''),
(13, 'Mexical Spiced Barramundi\r\n', 'with Kale, Sweet Potato, & Avocado Salad\r\n', 'The star of this meal is a simple-but-flavorful oil you\'ll make by combining cilantro, scallions, lime, olive oil, and a touch of honey for a balanced and aromatic topper for buttery chili-spiced barramundi fillets. The fish is served atop a Mexican-style salad made of charred corn kernels, mayo, sour cream, lime, chili powder, and feta.\r\n', '1.5 Tbsp Sour Cream*\r\n1/2 Cup Feta Cheese*\r\n1 teaspoon Chili Powder*\r\n10 oz Barramundi*\r\n1 Tsp Honey*\r\n2 Tbsp Mayonnaise*\r\n1 Lime*\r\n2 Scallions*\r\n1/4 oz Cilantro*\r\n1 Corn\r\n', 2, 2, 25, 550, 'Wash and dry produce. Drain and rinse corn; thoroughly pat dry with paper towels. Thinly slice scallions, separating whites from greens. Roughly chop cilantro. Zest and quarter lime.*Heat a large dry, preferably nonstick, pan over high heat. Add corn and a big pinch of sugar; cook, stirring occasionally, until lightly charred, 4-6 minutes. (TIP: Cover pan if corn begins to pop.) Turn off heat; transfer to a medium bowl. Wash out pan.*Stir scallion whites, mayonnaise, sour cream, feta, half the cilantro, juice from half the lime, salt, pepper, and as much chili powder as you like (save some for Step 3) into bowl with corn. Transfer to freezer to quickly cool. *In a small bowl, combine scallion greens, lime zest, half the honey, remaining cilantro, 1½ TBSP olive oil, juice from one lime wedge, salt, and pepper (all the honey, 3 TBSP olive oil, and juice from two lime wedges for 4 servings). Stir vigorously with a spoon until scallions and cilantro have wilted, 30-45 seconds.*Pat barramundi dry with paper towels. Season generously with salt, pepper, and as much remaining chili powder as you like. *Heat a drizzle of oil in pan used for corn over medium-high heat. Add barramundi, skin sides down; cook until skin is crispy, 4-5 minutes; flip and cook until opaque and cooked through, 2-3 minutes more. Divide esquites-style salad between plates. Top with barramundi. Drizzle cilantro-lime oil over barramundi or serve on the side for dipping. Serve.\r\n', '', '', '', '', ''),
(14, 'Mushroom & Potato Tacos\r\n', 'with Romaine & Orange Salad\r\n', 'For this hearty vegetarian meal, weʼre filling soft flour tortillas with mushrooms and potato — seasoned with a zesty, chorizo-inspired blend, then roasted. A pickled pepper relish lends bright flavor to the tacos, all tied together with a creamy sauce seasoned with the same spices. Our side salad of juicy orange and crunchy romaine rounds out the dish.\r\n', '4 Flour Tortillas*\r\n3 oz Radishes*\r\n1 Orange*\r\n¾ lb Yukon Gold Potatoes*\r\n6 oz Cremini Mushrooms*\r\n1 Shallot*\r\n3 Tbsps Roasted Peanuts*\r\n¼ cup Sour Cream*\r\n1 oz Sliced Pickled Jalapeño Pepper*\r\n1 oz Golden Or Red Sweet Piquante Peppers*\r\n1 Tbsp Spanish Spice Blend (Smoked Paprika, Ground Cumin, Ground Coriander, Dried Mexican Oregano, Cayenne Pepper, & Ground Cinnamon)*\r\n1 Romaine Lettuce Heart*\r\n2 Tbsps Rice Vinegar\r\n', 1, 2, 35, 650, 'Preheat the oven to 450°F. Wash and dry the fresh produce. Quarter the mushrooms. Quarter the potatoes lengthwise, then cut crosswise into 1/2-inch pieces. Place the vegetables on a sheet pan. Drizzle with olive oil and season with salt, pepper, and 3/4 of the spice blend; toss to coat. Arrange in an even layer. Roast 21 to 23 minutes, or until browned and tender when pierced with a fork. Remove from the oven.*While the vegetables roast, roughly chop the piquante peppers. Peel and small dice the shallot. Cut off and discard the root end of the lettuce; roughly chop the leaves. Peel and medium dice the orange. Cut off and discard the ends of the radishes; halve lengthwise, then thinly slice crosswise. Roughly chop the jalapeño pepper; thoroughly wash your hands and cutting board immediately after handling. In a bowl, combine the sour cream, a drizzle of olive oil, and as much of the remaining spice blend as you’d like (you may have extra). Season with salt and pepper to taste.*While the vegetables continue to roast, place the tortillas on a large piece of aluminum foil. Tightly wrap to seal. Place directly onto the oven rack and warm 5 to 7 minutes, or until heated through and pliable. Transfer to a work surface and carefully unwrap.*While the tortillas warm, in a medium bowl, combine the chopped piquante peppers, diced shallot, half the vinegar, and as much of the chopped jalapeño pepper as you’d like, depending on how spicy you’d like the dish to be. Drizzle with olive oil and season with salt and pepper to taste.*While the tortillas continue to warm, in a medium bowl, combine the chopped lettuce, diced orange, sliced radishes, peanuts, and remaining vinegar. Drizzle with olive oil and season with salt and pepper to taste.*Spread a layer of the seasoned sour cream onto the warmed tortillas. Top with the roasted vegetables and pepper relish. Serve the tacos with the salad on the side. Enjoy!\r\n', '', '', '', '', '');

